CREATE POLICY "Users can view appointment reminders V2" ON appointment_reminders AS PERMISSIVE FOR SELECT TO authenticated USING (((recipient_user_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
   FROM appointments a
  WHERE ((a.id = appointment_reminders.appointment_id) AND (((a.family_person_id IS NOT NULL) AND private.has_person_permission(a.family_id, a.family_person_id, 'appointments'::text, 'view'::text)) OR ((a.family_person_id IS NULL) AND private.has_family_permission(a.family_id, 'appointments'::text, 'view'::text))))))));

CREATE POLICY "Users can create appointment reminders V2" ON appointment_reminders AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((EXISTS ( SELECT 1
   FROM appointments a
  WHERE ((a.id = appointment_reminders.appointment_id) AND (a.family_person_id IS NOT NULL) AND private.has_person_permission(a.family_id, a.family_person_id, 'appointments'::text, 'create'::text)))));

CREATE POLICY family_person_view_labels_insert_own ON family_person_view_labels AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (((viewer_user_id = auth.uid()) AND (EXISTS ( SELECT 1
