CREATE POLICY family_person_view_labels_update_own ON family_person_view_labels AS PERMISSIVE FOR UPDATE TO authenticated USING ((viewer_user_id = auth.uid())) WITH CHECK (((viewer_user_id = auth.uid()) AND (EXISTS ( SELECT 1
